**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int nwd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

int main() {
    ifstream plik("pary.txt");
    int a, b;
    int ile = 0;
    while (plik >> a >> b) {
        int g = nwd(a, b);
        cout << a << " " << b << " -> NWD = " << g << endl;
        if (g > 1) ile++;
    }
    cout << "Pary nie wzglednie pierwsze: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm Euklidesa oblicza NWD zamieniajac pare (a, b) na (b, a mod b) dopoki b != 0. Para jest wzglednie pierwsza gdy NWD = 1.

